// Entry point of the assistant Worker (Cloudflare Workers). See src/app.js for the request flow.
// site-data.json is generated by build.py from content/*.json (npm run data); the deploy workflow
// recreates it before every deploy, so the Worker always matches the website.
import Anthropic from "@anthropic-ai/sdk";
import siteData from "./site-data.json";
import { createApp } from "./app.js";

export { IpLimiter, DailyBudget } from "./limiter.js";

const app = createApp({
  siteData,
  makeClient: (env) => new Anthropic({ apiKey: env.ANTHROPIC_API_KEY, maxRetries: 1, timeout: 25_000 }),
});

export default {
  fetch: (request, env, ctx) => app.fetch(request, env, ctx),
};
